// #9fd7c0e365af109a3e7787c2 (#7787c2) — в фильтре «בית עסק» на /admin/support длинное латинское имя
// видно с начала (ltr), обрезка — в конце с «…». Кейс SUP-003. Выбор фильтра данных не меняет — @prod-safe.
// Данные (не удалять): «QA-N14 International Holdings Limited Group», «QA Test Business A».
import { Locator } from '@playwright/test';
import { test, expect } from '../../fixtures';

const LONG_LATIN = 'QA-N14 International Holdings Limited Group';
const SHORT_LATIN = 'QA Test Business A';

/** Направление, обрезка и ширина выбранного текста против доступной ширины поля. */
function measure(select: Locator) {
  return select.evaluate((s: HTMLSelectElement) => {
    const cs = getComputedStyle(s);
    const ctx = document.createElement('canvas').getContext('2d')!;
    ctx.font = cs.font;
    const text = s.options[s.selectedIndex].text;
    return {
      text,
      direction: cs.direction,
      textOverflow: cs.textOverflow,
      textWidth: ctx.measureText(text).width,
      available: s.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight),
    };
  });
}

test.describe('Поддержка — фильтр «בית עסק»: латинское имя (#9fd7c0e365af109a3e7787c2)', () => {
  test('длинное латинское имя в фильтре «בית עסק» видно с начала, обрезано в конце @desktop @prod-safe #9fd7c0e365af109a3e7787c2', async ({ asUser }) => {
    const page = await asUser('admin');
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto('/admin/support');
    const business = page.getByLabel('בית עסק', { exact: true });
    await expect(business).toBeVisible();

    await business.selectOption({ label: LONG_LATIN });
    const long = await measure(business);
    expect(long.text).toBe(LONG_LATIN);
    // Источник: AC «תחילת שם העסק נראית תמיד, גם בשם לטיני ארוך; אם צריך לקצר, החיתוך בסוף השם».
    expect(long.direction, 'латинское имя должно идти слева направо — иначе срезается начало').toBe('ltr');
    expect(long.textWidth, 'имя должно быть шире поля, иначе обрезка не проверяется').toBeGreaterThan(long.available);
    expect(long.textOverflow, 'обрезка должна быть «…» в конце').toBe('ellipsis');

    await business.selectOption({ label: SHORT_LATIN });
    const short = await measure(business);
    expect(short.direction).toBe('ltr');
    expect(short.textWidth, 'короткое имя должно помещаться целиком').toBeLessThanOrEqual(short.available);
  });
});
